/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.ObsSpan;

class IssueAggregatorGroupUnitTest {

  private static ObsLog error(final long ts, final String src, final String level, final int line,
      final String trace) {
    String stack = "java.lang.IllegalStateException: order " + ts + " not found\n"
        + "\tat com.acme.orders.OrderService.find(OrderService.java:" + line + ")";
    return new ObsLog(ts, src, level, "com.acme.orders.OrderService", "failed", trace, null, stack,
        Map.of(), null, null);
  }

  @Test
  @DisplayName("A batch gives one group per source and fingerprint, with its count, first and last")
  void groups() {
    IssueAggregator aggregator = new IssueAggregator(null, null, true, "com.acme.", true, "salt");
    Map<String, IssueAggregator.Group> groups = aggregator
        .group(List.of(error(30, "api", "ERROR", 10, "t3"), error(10, "api", "ERROR", 11, "t1"),
            error(20, "api", "FATAL", 12, "t2"), error(15, "worker", "ERROR", 10, "t9"),
            new ObsLog(5, "api", "INFO", "x", "ok", null, null, null, Map.of(), null, null)));
    Assertions.assertEquals(2, groups.size());
    IssueAggregator.Group api = groups.values().iterator().next();
    Assertions.assertEquals(3, api.count);
    Assertions.assertEquals(10, api.first);
    Assertions.assertEquals("t3", api.last.traceId());
    Assertions.assertTrue(api.fatal);
  }

  private static ObsLog inRelease(final long ts, final String release) {
    String stack = "java.lang.IllegalStateException: boom\n"
        + "\tat com.acme.orders.OrderService.find(OrderService.java:10)";
    return new ObsLog(ts, "api", "ERROR", "com.acme.orders.OrderService", "failed", null, null,
        stack, Map.of(), release, "prod");
  }

  @Test
  @DisplayName("A resolved issue reopens only with a later release of the batch")
  void regressionByRelease() {
    IssueAggregator aggregator = new IssueAggregator(null, null, true, "com.acme.", true, "salt");
    IssueAggregator.Group old = aggregator
        .group(List.of(inRelease(10, "1.4.2"), inRelease(20, "1.4.1"))).values().iterator().next();
    Assertions.assertFalse(old.after("1.4.2"));
    Assertions.assertEquals("1.4.2", old.firstRelease);
    Assertions.assertEquals("1.4.1", old.lastRelease());
    IssueAggregator.Group newer = aggregator
        .group(List.of(inRelease(10, "1.4.2"), inRelease(30, "1.4.3"))).values().iterator().next();
    Assertions.assertTrue(newer.after("1.4.2"));
    Assertions.assertEquals("1.4.3", newer.lastRelease());
    Assertions.assertTrue(
        aggregator.group(List.of(inRelease(10, null))).values().iterator().next().after("1.4.2"));
  }

  @Test
  @DisplayName("Users and tenants are counted per issue, completed with the span of the trace")
  void affected() {
    IssueAggregator aggregator = new IssueAggregator(null, null, true, "com.acme.", true, "salt");
    String stack =
        "java.lang.IllegalStateException: boom\n\tat com.acme.orders.OrderService.find(OrderService.java:10)";
    List<ObsLog> logs = List.of(
        new ObsLog(1, "api", "ERROR", "x", "failed", "t1", null, stack, Map.of(), null, null),
        new ObsLog(2, "api", "ERROR", "x", "failed", "t2", null, stack, Map.of(), null, null),
        new ObsLog(3, "api", "ERROR", "x", "failed", "t3", null, stack,
            Map.of("enduser.id", "u-1", "app.tenant", "acme"), null, null),
        new ObsLog(4, "ui", "ERROR", "x", "failed", null, null, stack, Map.of("session.id", "s-9"),
            null, null));
    List<ObsSpan> spans = List.of(
        new ObsSpan(1, "api", "t1", "a", "", "GET /x", "SERVER", 1, "ERROR",
            Map.of("security.actor.uid", "u-1", "security.actor.tenant", "acme"), null, null),
        new ObsSpan(2, "api", "t2", "b", "", "GET /x", "SERVER", 1, "ERROR",
            Map.of("security.actor.uid", "u-2", "security.actor.tenant", "globex"), null, null));
    Map<String, IssueAggregator.Group> groups =
        aggregator.group(logs, IssueAggregator.contexts(spans));
    IssueAggregator.Group api = groups.values().iterator().next();
    Assertions.assertEquals(3, api.count);
    Assertions.assertEquals(2, api.users.estimate());
    Assertions.assertEquals(2, api.tenants.estimate());
    IssueAggregator.Group ui = groups.values().stream().skip(1).findFirst().orElseThrow();
    Assertions.assertEquals(1, ui.users.estimate());
  }
}
